const formMessage = document.getElementById('form-message');
const fullnameInput = document.getElementById('fullname');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');

function validateEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function validatePhone(phone) {
    if (!phone) return true;
    return /^[\d\s\-()]+$/.test(phone) && phone.replace(/\D/g, '').length >= 10;
}

function updateFieldError(input, isInvalid, errorMessage) {
    const fieldDiv = input.closest('.form-field');
    let errorEl = fieldDiv.querySelector('.error-text');

    if (isInvalid) {
        input.setAttribute('aria-invalid', 'true');
        if (!errorEl) {
            errorEl = document.createElement('p');
            errorEl.className = 'error-text';
            errorEl.id = `${input.id}-error`;
            input.setAttribute('aria-describedby', (input.getAttribute('aria-describedby') || '') + ` ${input.id}-error`);
            fieldDiv.appendChild(errorEl);
        }
        errorEl.textContent = errorMessage;
        errorEl.classList.add('show');
    } else {
        input.setAttribute('aria-invalid', 'false');
        if (errorEl) {
            errorEl.classList.remove('show');
        }
    }
}

function validateForm() {
    let isValid = true;
    let firstInvalidField = null;

    const fullnameValue = fullnameInput.value.trim();
    if (!fullnameValue) {
        updateFieldError(fullnameInput, true, 'Error: Full name is required.');
        isValid = false;
        if (!firstInvalidField) firstInvalidField = fullnameInput;
    } else {
        updateFieldError(fullnameInput, false);
    }

    const emailValue = emailInput.value.trim();
    if (!emailValue) {
        updateFieldError(emailInput, true, 'Error: Email is required.');
        isValid = false;
        if (!firstInvalidField) firstInvalidField = emailInput;
    } else if (!validateEmail(emailValue)) {
        updateFieldError(emailInput, true, 'Error: Enter a valid email like name@example.com.');
        isValid = false;
        if (!firstInvalidField) firstInvalidField = emailInput;
    } else {
        updateFieldError(emailInput, false);
    }

    const phoneValue = phoneInput.value.trim();
    if (phoneValue && !validatePhone(phoneValue)) {
        updateFieldError(phoneInput, true, 'Error: Enter a valid phone number.');
        isValid = false;
        if (!firstInvalidField) firstInvalidField = phoneInput;
    } else {
        updateFieldError(phoneInput, false);
    }

    if (!isValid && firstInvalidField) {
        firstInvalidField.focus();
    }

    return isValid;
}

fullnameInput.addEventListener('blur', () => {
    if (fullnameInput.value.trim()) {
        const fullnameValue = fullnameInput.value.trim();
        if (!fullnameValue) {
